export const BODY: string = "\n<p>ڈیزائنر WebP کو PNG میں اس لیے بدلتے ہیں کہ ان کا سافٹ ویئر WebP نہیں کھولتا۔ PNG ہر ایڈیٹر میں کھلتا ہے، WebP نہیں۔</p>\n<p>تبدیلی سے معیار نہیں گرتا، کیونکہ PNG بغیر نقصان کے محفوظ کرتا ہے۔ لیکن فائل بڑی ہو جاتی ہے۔ یہ مضمون بتاتا ہے کہ کب PNG چنیں اور کب WebP رکھیں۔</p>\n<p>تبدیل کرنے کے لیے <a href=\"/ur/webp-ko-png-mein-convert-karein/\">WebP ٹو PNG</a> استعمال کریں۔ عملی مراحل <a href=\"/ur/blog/webp-ko-png-rehnumai/\">WebP ٹو PNG گائیڈ</a> میں دیکھیں۔</p>\n<h2 id=\"why-designers-convert\">ڈیزائنر کیوں تبدیل کرتے ہیں</h2>\n<p>ڈیزائنر اس لیے تبدیل کرتے ہیں کہ ان کا سافٹ ویئر WebP نہیں کھولتا۔ Photoshop اور Figma کے پرانے ورژن WebP نہیں لیتے۔</p>\n<p>ڈیزائنر اس لیے بھی تبدیل کرتے ہیں کہ PNG میں ایڈیٹنگ آسان ہے۔ PNG ہر ٹول میں کھلتا ہے اور ہر ٹول اسے محفوظ کرتا ہے۔</p>\n<p>ڈیزائنر کے لیے مطابقت سب سے اہم ہے۔ اگر سافٹ ویئر فائل نہ کھولے تو کام رک جاتا ہے۔</p>\n<h2 id=\"editing-workflow\">ایڈیٹنگ کا ورک فلو</h2>\n<p>ایڈیٹنگ کا ورک فلو یہ ہے: WebP کو PNG میں بدلیں، PNG کو ایڈٹ کریں، اور حتمی فائل کو WebP میں محفوظ کریں۔ اصل WebP محفوظ رکھیں۔</p>\n<p>ورک فلو میں PNG صرف درمیانی مرحلہ ہے۔ حتمی فائل WebP میں رکھیں، تاکہ وہ چھوٹی رہے۔</p>\n<p>ورک فلو کو لکھ کر دیں، تاکہ ٹیم کے ہر رکن کو معلوم ہو کہ کب کون سا فارمیٹ استعمال کرنا ہے۔</p>\n<h2 id=\"transparency-for-designers\">ڈیزائنر کے لیے شفافیت</h2>\n<p>شفافیت ڈیزائنر کے لیے سب سے اہم ہے، کیونکہ لوگو اور آئیکن شفاف ہوتے ہیں۔ WebP سے PNG میں شفافیت بچتی ہے۔</p>\n<p>شفافیت جانچنے کے لیے تبدیل شدہ PNG کو رنگین پس منظر پر دیکھیں۔ اگر لوگو کے گرد سفید ڈبہ نہ ہو تو شفافیت بچ گئی ہے۔</p>\n<p>شفافیت کے لیے PNG چنیں، JPG نہیں۔ JPG شفافیت مٹا دیتا ہے۔</p>\n<h2 id=\"compatibility-map\">مطابقت کا نقشہ</h2>\n<p>مطابقت کا نقشہ یہ ہے: ویب براؤزر WebP لیتا ہے، ڈیزائن سافٹ ویئر اکثر نہیں لیتا، ای میل WebP نہیں لیتی، پرنٹر WebP نہیں لیتا۔</p>\n<p>نقشہ دیکھ کر فیصلہ کریں کہ کب کون سا فارمیٹ چنیں۔ ہر منزل کا اپنا فارمیٹ ہے۔</p>\n<p>نقشہ ہر سال بدلتا ہے، کیونکہ WebP کی سپورٹ بڑھ رہی ہے۔ ہر سال نقشہ جانچیں۔</p>\n<h2 id=\"when-png-wins\">PNG کب جیتتا ہے</h2>\n<p>PNG اس وقت جیتتا ہے جب ایڈیٹنگ کرنی ہو۔ PNG ہر ایڈیٹر میں کھلتا ہے اور شفافیت بچاتا ہے۔</p>\n<p>PNG اس وقت بھی جیتتا ہے جب تصویر کو بار بار محفوظ کرنا ہو۔ PNG بغیر نقصان کے محفوظ کرتا ہے، اس لیے معیار نہیں گرتا۔</p>\n<p>PNG اس وقت بھی جیتتا ہے جب تصویر میں متن ہو۔ PNG میں متن تیز رہتا ہے، WebP میں دھندلا ہو سکتا ہے۔</p>\n<h2 id=\"when-webp-wins\">WebP کب جیتتا ہے</h2>\n<p>WebP اس وقت جیتتا ہے جب تصویر ویب پر رہے۔ WebP چھوٹا ہے اور تیز لوڈ ہوتا ہے۔</p>\n<p>WebP اس وقت بھی جیتتا ہے جب فائل کا سائز اہم ہو۔ WebP PNG سے آدھا ہو سکتا ہے، بغیر معیار گرے۔</p>\n<p>WebP اس وقت بھی جیتتا ہے جب تصویر کو صرف دیکھنا ہو، ایڈٹ نہیں کرنا۔ دیکھنے کے لیے WebP کافی ہے۔</p>\n<h2 id=\"file-size-reality\">فائل سائز کی حقیقت</h2>\n<p>فائل سائز کی حقیقت یہ ہے کہ PNG WebP سے بہت بڑا ہوتا ہے۔ ایک ہی تصویر کی PNG فائل WebP سے دو گنا بڑی ہو سکتی ہے۔</p>\n<p>فائل سائز کی وجہ یہ ہے کہ PNG بغیر نقصان کے محفوظ کرتا ہے، جب کہ WebP نقصان کے ساتھ کمپریس کرتا ہے۔</p>\n<p>فائل سائز کا فیصلہ یہ ہے: ایڈیٹنگ کے لیے PNG کی بڑی فائل قبول کریں، ویب کے لیے WebP کی چھوٹی فائل رکھیں۔</p>\n<h2 id=\"colour-and-profiles\">رنگ اور پروفائل</h2>\n<p>رنگ پروفائل تصویر کے رنگوں کو طے کرتا ہے۔ WebP سے PNG میں رنگ پروفائل بچتا ہے، مگر کچھ پروفائل بدل سکتے ہیں۔</p>\n<p>رنگ جانچنے کے لیے تبدیل شدہ تصویر کو اصل سے ملا کر دیکھیں۔ اگر رنگ بدل گئے ہوں تو پروفائل جانچیں۔</p>\n<p>رنگ کی درستگی کے لیے اصل WebP محفوظ رکھیں اور PNG کو صرف کام کے لیے استعمال کریں۔</p>\n<h2 id=\"team-workflows\">ٹیم کا ورک فلو</h2>\n<p>ٹیم کے ورک فلو میں اصل WebP مشترکہ فولڈر میں رکھیں اور ہر رکن PNG نقل بنائے۔ اصل ایک جگہ رہے، نقل ہر ایک کے پاس۔</p>\n<p>ٹیم کے ورک فلو میں فائل کا نام واضح رکھیں: اصل کا نام webp، نقل کا نام png۔ نام سے معلوم ہو کہ کون سی اصل ہے۔</p>\n<p>ٹیم کے ورک فلو کو لکھ کر دیں، تاکہ کوئی غلطی نہ ہو۔ لکھا ہوا ورک فلو ہر کوئی پڑھ سکتا ہے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی یہ ہے کہ لوگ اصل WebP مٹا دیتے ہیں۔ اصل محفوظ رکھیں، کیونکہ PNG سے WebP واپس نہیں بنتا۔</p>\n<p>دوسری غلطی یہ ہے کہ لوگ پوری لائبریری کو PNG میں بدل دیتے ہیں۔ صرف وہی فائل بدلیں جو ایڈٹ کرنی ہو۔</p>\n<p>تیسری غلطی یہ ہے کہ لوگ PNG کو ویب پر لگا دیتے ہیں۔ ویب کے لیے WebP رکھیں، PNG صرف ایڈیٹنگ کے لیے ہے۔</p>\n<h2 id=\"decision-guide\">فیصلے کی رہنمائی</h2>\n<p>فیصلے کی رہنمائی یہ ہے: ایڈٹ کرنا ہے تو PNG، ویب پر دکھانا ہے تو WebP، بھیجنا ہے تو منزل دیکھیں۔</p>\n<p>رہنمائی کا دوسرا نکتہ یہ ہے: شفافیت چاہیے تو PNG، شفافیت نہ چاہیے تو JPG بھی چلتا ہے۔</p>\n<p>رہنمائی کا تیسرا نکتہ یہ ہے: اصل ہمیشہ WebP میں رکھیں، نقل PNG میں بنائیں۔</p>\n<h2 id=\"png-in-video-editing\">ویڈیو ایڈیٹنگ میں PNG</h2>\n<p>ویڈیو ایڈیٹنگ میں PNG استعمال ہوتا ہے، کیونکہ ویڈیو ایڈیٹر WebP نہیں لیتے۔ لوگو اور اوورلے PNG میں رکھیں۔</p>\n<p>ویڈیو میں PNG کی شفافیت اہم ہے، کیونکہ لوگو ویڈیو کے اوپر آتا ہے۔ شفاف PNG ویڈیو میں درست لگتا ہے۔</p>\n<p>ویڈیو کے لیے PNG کا سائز درست رکھیں۔ بڑا PNG ویڈیو کو سست کر دیتا ہے۔</p>\n<h2 id=\"png-in-3d-games\">تھری ڈی گیمز میں PNG</h2>\n<p>تھری ڈی گیمز میں PNG استعمال ہوتا ہے، کیونکہ گیم انجن WebP نہیں لیتا۔ ٹیکسچر اور آئیکن PNG میں رکھیں۔</p>\n<p>گیم میں PNG کی شفافیت اہم ہے، کیونکہ کردار کا پس منظر شفاف ہوتا ہے۔ شفاف PNG گیم میں درست لگتا ہے۔</p>\n<p>گیم کے لیے PNG کا سائز درست رکھیں۔ بڑا PNG گیم کو سست کر دیتا ہے۔</p>\n<h2 id=\"png-in-email-signatures\">ای میل دستخط میں PNG</h2>\n<p>ای میل دستخط میں PNG استعمال ہوتا ہے، کیونکہ ای میل کلائنٹ WebP نہیں کھولتا۔ دستخط کا لوگو PNG میں رکھیں۔</p>\n<p>ای میل دستخط کا PNG چھوٹا رکھیں، تاکہ ای میل بھاری نہ ہو۔ 200 پکسلز کا لوگو کافی ہے۔</p>\n<p>ای میل دستخط کے لیے شفاف PNG چنیں، تاکہ لوگو ہر ای میل کلائنٹ میں درست لگے۔</p>\n<h2 id=\"png-in-documentation\">دستاویز میں PNG</h2>\n<p>دستاویز، جیسے ورڈ یا پی ڈی ایف، میں PNG استعمال ہوتا ہے۔ دستاویز کا سافٹ ویئر WebP نہیں لیتا۔</p>\n<p>دستاویز میں PNG کی تصویر تیز رہتی ہے، خاص طور پر متن والی تصویر۔ اسکرین شاٹ PNG میں رکھیں۔</p>\n<p>دستاویز کے لیے PNG کا سائز درست رکھیں۔ بڑی تصویر دستاویز کو بھاری کر دیتی ہے۔</p>\n<h2 id=\"png-in-legal-medical\">قانونی اور طبی دستاویز میں PNG</h2>\n<p>قانونی اور طبی دستاویز میں PNG استعمال ہوتا ہے، کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ ثبوت کی تصویر میں معیار نہیں گرنا چاہیے۔</p>\n<p>قانونی دستاویز میں PNG کی تصویر کو ثبوت کے طور پر قبول کیا جاتا ہے، کیونکہ اس میں کوئی تبدیلی نہیں ہوتی۔</p>\n<p>قانونی اور طبی تصویر کو کبھی JPG میں نہ بدلیں، کیونکہ JPG معیار گراتا ہے۔ PNG رکھیں۔</p>\n<h2 id=\"png-in-presentations\">پریزنٹیشن میں PNG</h2>\n<p>پریزنٹیشن میں PNG استعمال ہوتا ہے، کیونکہ پاورپوائنٹ WebP نہیں لیتا۔ پریزنٹیشن کی تصویر PNG میں رکھیں۔</p>\n<p>پریزنٹیشن میں PNG کی شفافیت اہم ہے، کیونکہ لوگو سلائیڈ کے اوپر آتا ہے۔ شفاف PNG سلائیڈ میں درست لگتا ہے۔</p>\n<p>پریزنٹیشن کے لیے PNG کا سائز درست رکھیں۔ بڑی تصویر پریزنٹیشن کو سست کر دیتی ہے۔ مزید تفصیل <a href=\"/ur/blog/webp-ko-png-mein-kaise-convert-karein/\">WebP کو PNG میں کیسے بدلیں</a> میں اور عملی گائیڈ <a href=\"/ur/blog/webp-ko-png-rehnumai/\">WebP ٹو PNG گائیڈ</a> میں دیکھیں۔</p>\n";

